static inline const lt48_known_carrier *lt48_known_carrier_find(const char *key,unsigned d,unsigned f,unsigned p,const char *hash){
 if(!key||!hash)return NULL;
 for(size_t i=0;i<sizeof(known_carriers)/sizeof(*known_carriers);i++){const lt48_known_carrier *r=known_carriers+i;if(r->definition==d&&r->family==f&&r->pinmap==p&&!strcmp(r->key,key)&&!strcmp(r->source_sha256,hash))return r;}
 return NULL;
}
